local PRODUCTS = {
    iron_slurrymixer = { name = "Železni mešalec livarske kaše", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni mešalec livarske kaše za livarje." },
    bronze_slurrymixer = { name = "Bronast mešalec livarske kaše", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast mešalec livarske kaše za livarje." },
    silver_slurrymixer = { name = "Srebrn mešalec livarske kaše", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn mešalec livarske kaše za livarje." },
    gilded_slurrymixer = { name = "Pozlačen mešalec livarske kaše", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen mešalec livarske kaše za livarje." },
    jewel_set_slurrymixer = { name = "Draguljast mešalec livarske kaše", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast mešalec livarske kaše za livarje." },
    royal_sovereign_slurrymixer = { name = "Kraljevski suveren mešalec livarske kaše", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren mešalec livarske kaše z biseri za krono." },
}
local BUILDINGS = {
    slurrymixer_workshop = { name = "Slurrymixer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    slurrymixer_house = { name = "Slurrymixer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_slurrymixer_atelier = { name = "Mojstrski slurrymixer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_slurrymixer_palace = { name = "Suverena slurrymixer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SlurryMixerMaker.ironStock=16; SlurryMixerMaker.bronzeStock=12; SlurryMixerMaker.woodStock=14; SlurryMixerMaker.leatherStock=8; SlurryMixerMaker.silverStock=8; SlurryMixerMaker.goldStock=6; SlurryMixerMaker.jewelStock=4; SlurryMixerMaker.pearlStock=4
SlurryMixerMaker.productStock = {}; SlurryMixerMaker.buildings = {}; SlurryMixerMaker.maker = nil; SlurryMixerMaker.activeMaking = {}; SlurryMixerMaker.totalProducts = 0; SlurryMixerMaker.dayTimer = 0
function SlurryMixerMaker.init() SlurryMixerMaker.ironStock=16; SlurryMixerMaker.bronzeStock=12; SlurryMixerMaker.woodStock=14; SlurryMixerMaker.leatherStock=8; SlurryMixerMaker.silverStock=8; SlurryMixerMaker.goldStock=6; SlurryMixerMaker.jewelStock=4; SlurryMixerMaker.pearlStock=4; SlurryMixerMaker.productStock={}; SlurryMixerMaker.buildings={}; SlurryMixerMaker.maker=nil; SlurryMixerMaker.activeMaking={}; SlurryMixerMaker.totalProducts=0; SlurryMixerMaker.dayTimer=0; print("[SlurryMixerMaker] Royal Slurry Mixer Maker System initialized (6 products, 4 buildings)") end
function SlurryMixerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SlurryMixerMaker.maker={name=n or ("Mešar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mešar najet: %s (spretnost: %d)",SlurryMixerMaker.maker.name,s),"success") end; return true end
function SlurryMixerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SlurryMixerMaker.build(id) local ok,e=SlurryMixerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SlurryMixerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SlurryMixerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SlurryMixerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SlurryMixerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SlurryMixerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SlurryMixerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SlurryMixerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SlurryMixerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SlurryMixerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SlurryMixerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SlurryMixerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SlurryMixerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SlurryMixerMaker.buildings==0 then return false,"Potrebna mešalna delavnica" end; if not SlurryMixerMaker.maker then return false,"Potreben mešar" end; return true end
function SlurryMixerMaker.make(pt,qty) qty=qty or 1; local ok,e=SlurryMixerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SlurryMixerMaker.ironStock=SlurryMixerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SlurryMixerMaker.bronzeStock=SlurryMixerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SlurryMixerMaker.woodStock=SlurryMixerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SlurryMixerMaker.leatherStock=SlurryMixerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SlurryMixerMaker.silverStock=SlurryMixerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SlurryMixerMaker.goldStock=SlurryMixerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SlurryMixerMaker.jewelStock=SlurryMixerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SlurryMixerMaker.pearlStock=SlurryMixerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SlurryMixerMaker.maker then t=math.max(1,t-math.floor(SlurryMixerMaker.maker.skill/13)) end; table.insert(SlurryMixerMaker.activeMaking,{id="slurrymixer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SlurryMixerMaker.completeMaking(m) local q=1.0+(SlurryMixerMaker.getQualityBonus()/100); if SlurryMixerMaker.maker then q=q+(SlurryMixerMaker.maker.skill/140) end; q=math.min(2.5,q); SlurryMixerMaker.productStock[m.productType]=(SlurryMixerMaker.productStock[m.productType] or 0)+m.quantity; SlurryMixerMaker.totalProducts=SlurryMixerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SlurryMixerMaker.maker then SlurryMixerMaker.maker.itemsMade=SlurryMixerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SlurryMixerMaker.maker.skill=math.min(100,SlurryMixerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mešalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"slurrymixer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SlurryMixerMaker.update(dt) if not _G.state then return end; SlurryMixerMaker.dayTimer=SlurryMixerMaker.dayTimer+dt; if SlurryMixerMaker.dayTimer>=30 then SlurryMixerMaker.dayTimer=0; for i=#SlurryMixerMaker.activeMaking,1,-1 do local m=SlurryMixerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SlurryMixerMaker.completeMaking(m); table.remove(SlurryMixerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SlurryMixerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SlurryMixerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SlurryMixerMaker.getStats() return {ironStock=SlurryMixerMaker.ironStock,bronzeStock=SlurryMixerMaker.bronzeStock,woodStock=SlurryMixerMaker.woodStock,leatherStock=SlurryMixerMaker.leatherStock,silverStock=SlurryMixerMaker.silverStock,goldStock=SlurryMixerMaker.goldStock,jewelStock=SlurryMixerMaker.jewelStock,pearlStock=SlurryMixerMaker.pearlStock,productStock=SlurryMixerMaker.productStock,numBuildings=#SlurryMixerMaker.buildings,hasMaker=SlurryMixerMaker.maker~=nil,makerName=SlurryMixerMaker.maker and SlurryMixerMaker.maker.name or "—",makerSkill=SlurryMixerMaker.maker and SlurryMixerMaker.maker.skill or 0,activeMaking=#SlurryMixerMaker.activeMaking,totalProducts=SlurryMixerMaker.totalProducts} end
return SlurryMixerMaker
